import{_ as n,a0 as r,w as s,s as u,I as a,x as p,a1 as l,A as o,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Ubuntu server 中設置 RainLoop Webmail | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu server 中設置 RainLoop Webmail | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu server 中設置 RainLoop Webmail | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu server 中設置 RainLoop Webmail | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/How to set up RainLoop webmail in Ubuntu server","title":"如何在 Ubuntu server 中設置 RainLoop Webmail","tag":"201404","desc":""},"relativePath":"201404/How to set up RainLoop webmail in Ubuntu server.md","filePath":"[post].md"}'),m={name:"201404/How to set up RainLoop webmail in Ubuntu server.md"};function d(b,t,f,w,L,T){const e=r("Link");return s(),u("div",null,[t[22]||(t[22]=a("h1",{id:"如何在-ubuntu-server-中設置-rainloop-webmail",tabindex:"-1"},[p("如何在 Ubuntu server 中設置 RainLoop Webmail "),a("a",{class:"header-anchor",href:"#如何在-ubuntu-server-中設置-rainloop-webmail","aria-label":"Permalink to “如何在 Ubuntu server 中設置 RainLoop Webmail”"},"​")],-1)),t[23]||(t[23]=a("p",null,"Webmail無疑是任何郵件服務器必不可少的一部分。雖然本地郵件客户端通常比Webmail的功能更多，但通過電子郵件客户端從外部可信的網絡訪問IMAP或SMTP有時會很棘手。再者，當你需要在一個特定的工作站、筆記本電腦或者移動設備去使用一個電子郵件客户端時，你可以在任何地方使用Webmail服務，只要你接入互聯網。",-1)),a("p",null,[t[1]||(t[1]=p("本教程的重點是在一個運行 Apache 的 Ubuntu 服務器上安裝配置",-1)),l(e,{href:"http://rainloop.net/"},{default:o(()=>[...t[0]||(t[0]=[p("RainLoop",-1)])]),_:1}),t[2]||(t[2]=p(" Webmail。RainLoop 是基於 PHP 的Webmail，並且有以下功能。",-1))]),t[24]||(t[24]=i(`<ul><li>支持apache，nginx和其它網頁服務器。</li><li>標準接口補充了一個主題庫可供選擇。</li><li>個人和非盈利項目可免費使用。</li></ul><p>在寫這篇文章時，RainLoop 還不支持郵件過濾和不在公司時的自動回覆。</p><h3 id="在-ubuntu-服務器上安裝-rainloop" tabindex="-1">在 Ubuntu 服務器上安裝 RainLoop <a class="header-anchor" href="#在-ubuntu-服務器上安裝-rainloop" aria-label="Permalink to “在 Ubuntu 服務器上安裝 RainLoop”">​</a></h3><p>首先，在服務器上設置必備的軟件包。</p><pre><code># apt-get install wget unzip apache2 php5 php5-mysql libmysqlclient15-dev mysql-server poppassd 
</code></pre><p>接下來，下載和安裝 RainLoop。</p><pre><code># mkdir /var/www/webmail
# cd /var/www/webmail
# wget http://repository.Rainloop.net/v1/Rainloop-1.6.3.706-e3c14e17bc4370a1561bcc68d1d494fd.zip
# unzip Rainloop-1.6.3.706-e3c14e17bc4370a1561bcc68d1d494fd.zip
# rm Rainloop-*.zip 
</code></pre><p>然後設置必要的權限。</p><pre><code># cd /var/www/webmail
# find . -type d -exec chmod 755 {} \\;
# find . -type f -exec chmod 644 {} \\;
# chown –R www-data:www-data /var/www/webmail 
</code></pre><p>我們馬上就可以使用 RainLoop 了。最後，通過管理面板進行調整，接下來會有詳細描述。</p><h3 id="通過管理面板首次配置" tabindex="-1">通過管理面板首次配置 <a class="header-anchor" href="#通過管理面板首次配置" aria-label="Permalink to “通過管理面板首次配置”">​</a></h3><p>很多配置參數通過一款界面友好的管理面板就能調整。使用以下憑證進入管理面板。</p>`,12)),a("ol",null,[a("li",null,[t[4]||(t[4]=p("URL: ",-1)),l(e,{href:"http://IP/webmail/?admin"},{default:o(()=>[...t[3]||(t[3]=[p("http://IP/webmail/?admin",-1)])]),_:1})]),t[5]||(t[5]=a("li",null,"user: admin",-1)),t[6]||(t[6]=a("li",null,"Pass: 12345",-1))]),t[25]||(t[25]=i(`<p>當然，建議儘快修改默認密碼。我們將使用管理面板去調整一下設置。</p><h3 id="增加郵件域" tabindex="-1">增加郵件域 <a class="header-anchor" href="#增加郵件域" aria-label="Permalink to “增加郵件域”">​</a></h3><p>在 管理面板&gt; 域&gt; 增加域 頁面設置有效的域。建議服務器 IP 是本地服務器，如 127.0.0.1。基於服務器配置，RainLoop 可以配置使用 IMAP/IMAPS 或 SMTP/SMTPS。並且，確認‘使用短登錄表單’複選框已勾選。</p><p><img src="http://farm4.staticflickr.com/3736/12603680854_eb22bd8eb8_z.jpg" alt=""></p><p>使用‘測試連接’按鈕驗證設置。</p><h3 id="啓用聯繫人" tabindex="-1">啓用聯繫人 <a class="header-anchor" href="#啓用聯繫人" aria-label="Permalink to “啓用聯繫人”">​</a></h3><p>聯繫人功能需要資料庫支持。我們將使用 MySQL 資料庫啓用聯繫人。RainLoop 可以手動創建所需的資料庫，如下。</p><pre><code># mysql -u root -p 

mysqlcreate database rainloop;
mysqlexit;
</code></pre><p>現在這個功能可以通過管理面板&gt;聯繫人頁面啓用。</p><p><img src="http://farm8.staticflickr.com/7452/12603262215_2299bdafc5_z.jpg" alt=""></p><p>再來一次，使用‘測試’按鈕檢查設置。</p><h3 id="啓動密碼更改插件" tabindex="-1">啓動密碼更改插件 <a class="header-anchor" href="#啓動密碼更改插件" aria-label="Permalink to “啓動密碼更改插件”">​</a></h3><p>在多數 linux 的郵件賬户的郵件服務器是用自己的 UID 和 GID 操作系統的實際用户。因此，在過去更改這些賬户的密碼是很棘手的。幸好，今天有工具可以完成這個工作。這個工具是 poppassd。</p><p>第一步是在服務器上安裝 poppassd，可以用 apt-get 來完成。</p><pre><code># apt-get install poppassd 
</code></pre><p>接下來，去允許 RainLoop 使用 poppassd，從 管理面板&gt; 軟件包 頁面安裝 RainLoop 插件 poppassd。</p><p><img src="http://farm4.staticflickr.com/3734/12603357113_a966caf534_z.jpg" alt=""></p><p>最後，poppassd 插件可以從 管理面板&gt; 插件頁面啓用。</p><p><img src="http://farm8.staticflickr.com/7356/12603681254_56fc0b3e9f_z.jpg" alt=""></p><p>現在所有參數已設置，用户可以從他們提供的憑證登錄，如截圖所示。</p>`,20)),a("ul",null,[a("li",null,[t[8]||(t[8]=p("URL: ",-1)),l(e,{href:"http://IP/webmail"},{default:o(()=>[...t[7]||(t[7]=[p("http://IP/webmail",-1)])]),_:1})]),t[9]||(t[9]=a("li",null,"user: user@domain",-1)),t[10]||(t[10]=a("li",null,"pass: password",-1))]),t[26]||(t[26]=a("p",null,[a("img",{src:"http://farm4.staticflickr.com/3721/12603357333_724fbddaff_z.jpg",alt:""})],-1)),t[27]||(t[27]=a("p",null,"希望這篇文章能幫助到你。",-1)),t[28]||(t[28]=a("hr",null,null,-1)),a("p",null,[t[12]||(t[12]=p("via: ",-1)),l(e,{href:"http://xmodulo.com/2014/02/rainloop-webmail-ubuntu-server.html"},{default:o(()=>[...t[11]||(t[11]=[p("http://xmodulo.com/2014/02/rainloop-webmail-ubuntu-server.html",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=p("譯者：",-1)),l(e,{href:"https://github.com/vito-L"},{default:o(()=>[...t[13]||(t[13]=[p("Vito",-1)])]),_:1}),t[16]||(t[16]=p(" 校對：",-1)),l(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[14]||(t[14]=[p("Caroline",-1)])]),_:1})]),a("p",null,[t[19]||(t[19]=p("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[p("LCTT",-1)])]),_:1}),t[20]||(t[20]=p(" 原創翻譯，",-1)),l(e,{href:"http://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[p("Linux中國",-1)])]),_:1}),t[21]||(t[21]=p(" 榮譽推出",-1))])])}const P=n(m,[["render",d]]);export{v as __pageData,P as default};
